def H(t):return f'<h2>{t}</h2>'
def Pp(t):return f'<p>{t}</p>'
def UL(items,tag='ul'):return f'<{tag}>'+''.join(f'<li>{i}</li>' for i in items)+f'</{tag}>'
def TAB(rows,head):return '<table><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
def kz(x,n=1):return f'{x:.{n}f}'.replace('.',',')

# ---------- re-simulation of the Simulink PID model (Euler, dt = 0.01 s) ----------
def sim(P,I,D,N=0.5,dt=0.01,Tend=1500,dist=False,clamp=True):
    n=int(Tend/dt);buf=np.zeros(int(30/dt));bi=0;xi=xd=xa=xo=xs=xf=0.0;ts=[];ys=[];us=[]
    for k in range(n):
        t=k*dt;r=0.1 if (t>=50 and not dist) else 0;Dd=1 if (t>=50 and dist) else 0
        e=r-xs;u=P*e+xi+D*N*(e-xd);us_=min(25,max(-75,u))
        if not(clamp and u!=us_ and np.sign(u)==np.sign(e)):xi+=dt*I*e
        xd+=dt*N*(e-xd);xa+=dt*(us_-xa)/10;dl=buf[bi];buf[bi]=xa;bi=(bi+1)%len(buf)
        xo+=dt*(0.02*dl-xo)/180;xf+=dt*(0.2*Dd-xf)/60;y=xo-xf;xs+=dt*(y-xs)
        if k%50==0:ts.append(t);ys.append(y);us.append(us_)
    return np.array(ts),np.array(ys),np.array(us)
def metr(ts,ys):
    yf=ys[-1];o=np.where(abs(ys-yf)>0.05*yf)[0];return (ys.max()-yf)/yf*100,ts[o[-1]]-50
