def timeline():
    segs=[('1–3',45,'Мақсат'),('4–5',60,'Объект'),('6–9',90,'ПИД'),('10–11',60,'Fuzzy'),('12',20,''),('13–14',45,'Салыст.'),('15–17',75,'Статист.'),('18',25,'')]
    o='';x=10;k=320/420
    for i,(sl,sec,nm) in enumerate(segs):
        w=sec*k;c='bxa' if sl=='6–9' else 'bx'
        o+=R(x,60,w,40,c,3)+T(x+w/2,84,f'{sec}','t-s t-b')
        o+=T(x+w/2,52 if i%2==0 else 116,sl,'t-s mu')
        if nm:o+=T(x+w/2,34 if i%2==0 else 134,nm,'t-s')
        x+=w
    o+=A(10,160,330,160,two=True)+T(170,178,'≈ 420 с = 7 мин (сандар — секунд)','t-s')+T(170,198,'жоғарғы/төменгі қатар — слайд нөмірлері','t-s mu')
    return o
