    o+='<path d="M'+' L'.join(f'{X(t):.1f} {Yp(1.3+y):.1f}' for t,y in zip(TS,YS))+'" class="lna"/>'
    o+='<path d="M'+' L'.join(f'{X(t):.1f} {Yu(75+u):.1f}' for t,u in zip(TS,US))+'" class="lna"/>'
