    for u in (75,80,100):o+=f'<line x1="{x0}" y1="{Yu(u):.1f}" x2="334" y2="{Yu(u):.1f}" class="ln dash"/>'+TR(x0-3,Yu(u)+4,str(u),'t-s')
    o+=TL(250,26,'P, МПа','t-s t-b')+TL(250,Yu(90)+4,'клапан, %','t-s t-b')+TL(150,Yp(1.4)-5,'P = Pmax = 1,4','t-s ac')
    o+=T(X(50),216,'50 с','t-s')+T(X(700)-10,216,'700 с','t-s')+TL(X(150),Yu(100)+14,'+25 % шекте','t-s mu')
    return o
