def fuzzyloop():
    y=80;o=C(22,y,9,'bx')+A(0,y,13,y)+T(10,y-14,'Pтап','t-s')
    o+=A(31,y,58,y)+T(44,y-6,'e','t-s')+C(66,y,2.5,'hda')
    o+=P([(66,y),(66,40),(82,40)])+B(82,26,58,28,'s/(5s+1)','bx','t-s')+P([(140,40),(160,40),(160,y-8)])+TL(144,34,'de','t-s')
    o+=A(66,y,150,y)+B(150,64,22,32,'Mux','bx','t-s')[:0]+R(150,64,20,32,'bx',2)+A(170,y,180,y)
    o+=B(180,62,58,36,'FLC\n25 ереже','bxa','t-s',lh=13)+A(238,y,248,y)+T(243,y-6,'du','t-s')
    o+=B(248,66,26,28,'1/s','bx','t-s')+A(274,y,290,y)+B(290,66,40,28,'шек','bx','t-s')
    o+=P([(310,94),(310,130),(170,130)])+B(110,116,60,28,'объект','bx','t-s')+P([(110,130),(22,130),(22,89)])+T(32,106,'−','t-b')
    o+=T(310,108,'u','t-s')+T(170,170,'du-ды интегратор жинайды → статикалық қате жоқ','t-s')+T(170,188,'ауқымдар: e ±0,25; de ±0,0025; du ±0,3 %/с','t-s mu')
    return o
