def poissonfig():
    X=lambda v:30+(v-6)/24*290
    o=L(20,80,330,80)+''.join(L(X(v),76,X(v),84)+T(X(v),100,str(v),'t-s') for v in (6,10,14,18,22,26,30))
    o+=f'<rect x="{X(18-sd):.1f}" y="64" width="{X(18+sd)-X(18-sd):.1f}" height="28" rx="4" class="soft"/>'
    o+=L(X(18),56,X(18),104,'lna')+T(X(18),48,'күтілгені λT = 18','t-s ac')+C(X(21),80,5,'hda')+T(X(21),124,'нәтиже 21','t-s t-b')
    o+=T(170,150,'±√18 ≈ ±4,2 — Пуассон шашырауы; 21 — 1σ ішінде','t-s')
    return o
